#!/usr/bin/env node
/**
 * Static endpoint audit: every table / RPC / storage bucket / Netlify function the client calls must exist.
 *   tables, RPCs, buckets  -> e2e/lib/schema.json (regenerated by `bash e2e/sql/run.sh` from all migrations)
 *   function URLs          -> netlify/functions/<name>.* or a `config.path` declared in a function
 * Walks only files reachable from src/main.tsx (live code), so dead files don't create noise.
 * Exit 1 on any missing target. Run: npm run audit:endpoints
 */
import fs from 'node:fs';
import path from 'node:path';
const root = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..');
const src = path.join(root, 'src');
const schema = JSON.parse(fs.readFileSync(path.join(root, 'e2e/lib/schema.json'), 'utf8'));
const tables = new Set(Object.keys(schema.tables));
const rpcs = new Set(Object.keys(schema.rpc));
const _b = schema.storage.buckets || {}; const buckets = new Set(Array.isArray(_b) ? _b.map((b) => (typeof b === 'string' ? b : b.id || b.name)) : Object.keys(_b));

// ---- live-file closure from main.tsx
const exts = ['.ts', '.tsx', '.js', '.jsx', '/index.ts', '/index.tsx'];
const resolveImport = (from, spec) => {
  if (!spec.startsWith('.')) return null;
  const base = path.resolve(path.dirname(from), spec);
  for (const e of ['', ...exts]) { const f = base + e; if (fs.existsSync(f) && fs.statSync(f).isFile()) return f; }
  return null;
};
const live = new Set();
const queue = [path.join(src, 'main.tsx')];
while (queue.length) {
  const f = queue.pop();
  if (!f || live.has(f)) continue; live.add(f);
  const t = fs.readFileSync(f, 'utf8');
  for (const m of t.matchAll(/(?:from\s+|import\s*\(\s*|require\(\s*|import\s+)['"](\.[^'"]+)['"]/g)) queue.push(resolveImport(f, m[1]));
}
const isTest = (f) => /__tests__|\.test\.|test-utils|\/tests\//.test(f);

// ---- Netlify function inventory
const fnDir = path.join(root, 'netlify/functions');
const fnNames = new Set(); const fnPaths = [];
for (const f of fs.readdirSync(fnDir)) {
  const full = path.join(fnDir, f);
  if (!fs.statSync(full).isFile() || !/\.(ts|js|mjs)$/.test(f) || f.startsWith('_')) continue;
  fnNames.add(f.replace(/\.[^.]+$/, ''));
  const t = fs.readFileSync(full, 'utf8');
  for (const m of t.matchAll(/path\s*:\s*(\[[^\]]*\]|['"][^'"]+['"])/g)) for (const p of m[1].matchAll(/['"]([^'"]+)['"]/g)) fnPaths.push(p[1]);
}
const pathMatches = (url) => fnPaths.some((p) => p === url || (p.endsWith('/*') && url.startsWith(p.slice(0, -1))) || (p.includes(':') && new RegExp('^' + p.replace(/:[^/]+/g, '[^/]+') + '$').test(url)));

const missing = []; const used = { tables: new Set(), rpcs: new Set(), buckets: new Set(), fns: new Set() };
const add = (kind, name, file, line) => { used[kind].add(name); };
for (const f of live) {
  if (isTest(f)) continue;
  const t = fs.readFileSync(f, 'utf8'); const rel = path.relative(root, f);
  const lineOf = (i) => t.slice(0, i).split('\n').length;
  for (const m of t.matchAll(/storage\s*\.\s*from\(\s*(?:['"]([\w-]+)['"]|([A-Z_][A-Z0-9_]*))\s*\)/g)) {
    let name = m[1];
    if (!name) { const c = t.match(new RegExp(`const\\s+${m[2]}\\s*=\\s*['"]([\\w-]+)['"]`)); name = c ? c[1] : null; }
    if (!name) { missing.push(`${rel}:${lineOf(m.index)} storage bucket constant ${m[2]} could not be resolved`); continue; }
    used.buckets.add(name); if (!buckets.has(name)) missing.push(`${rel}:${lineOf(m.index)} storage bucket "${name}"`);
  }
  for (const m of t.matchAll(/(?<!storage\s*)\.\s*from\(\s*['"]([\w.]+)['"]/g)) { if (m[1].includes('.')) continue; used.tables.add(m[1]); if (!tables.has(m[1])) missing.push(`${rel}:${lineOf(m.index)} table/view "${m[1]}"`); }
  for (const m of t.matchAll(/\.rpc\(\s*['"]([\w]+)['"]/g)) { used.rpcs.add(m[1]); if (!rpcs.has(m[1])) missing.push(`${rel}:${lineOf(m.index)} rpc "${m[1]}"`); }
  for (const m of t.matchAll(/['"`](\/(?:api|\.netlify\/functions)\/[\w\-/.]+)/g)) {
    const url = m[1].replace(/\/$/, ''); used.fns.add(url);
    const fn = url.startsWith('/.netlify/functions/') ? url.split('/')[3] : null;
    const ok = fn ? fnNames.has(fn) : pathMatches(url) || [...fnPaths].some((p) => url.startsWith(p + '/'));
    if (!ok) missing.push(`${rel}:${lineOf(m.index)} function URL "${url}"`);
  }
}
const uncalled = [...fnNames].filter((n) => ![...used.fns].some((u) => u.endsWith('/' + n) || u.includes('/' + n + '/')) );
console.log(`live files: ${live.size}  tables: ${used.tables.size}  rpcs: ${used.rpcs.size}  buckets: ${used.buckets.size}  function URLs: ${used.fns.size}`);
if (uncalled.length) console.log(`functions with no literal client URL (may be called via config.path/gateway/schedule): ${uncalled.join(', ')}`);
if (missing.length) { console.error('\nMISSING TARGETS:\n  ' + [...new Set(missing)].join('\n  ')); process.exit(1); }
console.log('OK: every client-called table, RPC, bucket and function exists.');
